const mA = Math.max(0.1, P.mA), mB = Math.max(0.1, P.mB), F = Math.abs(P.F);
// Two skaters push off. SAME force magnitude on each (3rd law), opposite
// directions. They accelerate apart; lighter one moves faster: a = F/m.
const aA = F / mA, aB = F / mB;
const phase = 2.2;                       // push lasts a moment, then coast/reset
const tc = t % 5;
const tp = Math.min(tc, phase);
// displacement during push (const accel), then constant-velocity coast
let xA, xB;
const dPush = 0.5;                        // scale displacement to fit on-screen
if (tc <= phase) {
  xA = -1 - 0.5 * aA * tp * tp * dPush;
  xB =  1 + 0.5 * aB * tp * tp * dPush;
} else {
  const vA = aA * phase, vB = aB * phase, dt = tc - phase;
  xA = -1 - (0.5 * aA * phase * phase + vA * dt) * dPush;
  xB =  1 + (0.5 * aB * phase * phase + vB * dt) * dPush;
}
xA = Math.max(-9.4, xA); xB = Math.min(9.4, xB);
const y0 = 0;
v.line(-10, y0, 10, y0, { color: H.colors.axis, width: 2 });
// blocks sized by mass
const sA = 0.5 + mA * 0.18, sB = 0.5 + mB * 0.18;
v.rect(xA - sA / 2, y0, sA, sA, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
v.rect(xB - sB / 2, y0, sB, sB, { fill: H.colors.accent2, stroke: H.colors.bg, width: 2 });
// equal & opposite force arrows during the push
if (tc <= phase) {
  const fLen = Math.min(4, F * 0.6);
